window.AUTH=window.AUTH||{};window.AUTH["17-43"]={"d":"17-43","id":"2017/17-43","n":"Dahda v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Los R. Dahda","date":"2017-11-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-43/22106/20171130135510500_17-43ts.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondent United States","date":"2018-01-05","url":"https://www.supremecourt.gov/DocketPDF/17/17-43/26909/20180105163452629_17-43bsUnitedStates.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner Los R. Dahda","date":"2018-02-05","url":"https://www.supremecourt.gov/DocketPDF/17/17-43/34361/20180205112011600_Dahda%20reply%20brief%20for%20petitioners.pdf","side":"pet","n":33}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Adams v. Lankford","cite":"788 F.2d 1493","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/788/1493/","by":{"0":"30","2":"13"}},{"t":"case","label":"Berger v. New York","cite":"388 U.S. 41","y":1967,"id":"1966/615","sc":1,"sum":"The language of § 813-a is too broad in its sweep resulting in a trespassory intrusion into a constitutionally protected area, and is, therefore, violative of the Fourth and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","2":"9"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Gelbard v. United States","cite":"408 U.S. 41","y":1972,"id":"1971/71-110","sc":1,"sum":"In a 5-4 majority opinion written by Justice William Brennan, the Court held that the federal statute barring the use of evidence obtained through illegally intercepted communications also serves as a valid defense to civil contempt charges.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"17","2":"19"}},{"t":"case","label":"(III) Cases—continued: Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"24","2":"8"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Moore v. Mitchell","cite":"281 U.S. 18","y":1930,"id":"scdb/1929-096","sc":1,"sum":"A state tax officer, claiming only by virtue of his office and authorized only by the laws of his State, has no legal capacity to sue, for the collection of taxes due to his State, in a federal court in another State. P. 23. 30 F. (2d) 600, affirmed. CERTIORARI, 279 U. S. 834, to review a judgment of the Circuit Court of Appeals which affirmed a judgment of MOORE v. MITCHELL. Argument for Petitioner. the District …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Riley v. California","cite":"134 S. Ct. 2473","y":2014,"id":"2013/13-132","sc":1,"sum":"The Court found that the San Diego Police Department's search of an arrested gang member's cell phone pictures without a warrant violated the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"32","2":"3, 14"}},{"t":"case","label":"Schindler Elevator Corp. v. United States ex rel. Kirk","cite":"563 U.S. 401","y":2011,"id":"2010/10-188","sc":1,"sum":"The Court held that a whistleblower may not use information obtained through Freedom of Information Act requests to allege violations of the Federal Claims Act by a government contractor.","sumSrc":"Oyez","by":{"0":"22","1":"16"}},{"t":"case","label":"United States v. Acon","cite":"513 F.2d 513","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/513/513/","by":{"0":"29, 30"}},{"t":"case","label":"United States v. Chavez","cite":"416 U.S. 562","y":1974,"id":"1973/72-1319","sc":1,"ar":7,"sum":"Stating that Section 2518(10)(a) “provides the remedy for the right created by section 2515”.","sumSrc":"brief:0","by":{"0":"passim","1":"19, 20","2":"passim"}},{"t":"case","label":"United States v. Donovan","cite":"429 U.S. 413","y":1977,"id":"1976/75-212","sc":1,"sum":"Title 18 U. S. C. § 2518 (1) (b) (iv), which is part of Title III of the Omnibus Crime Control and Safe Streets Act of 1968, requires the Government to include in its wiretap applications \"the identity of the person, if known, committing the offense and whose communications are to be intercepted.\" Section 2518 (8) (d) requires the judge to whom a wiretap application is made to cause to be served on the persons named …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","1":"5, 20, 21, 26"}},{"t":"case","label":"United States v. Giordano","cite":"416 U.S. 505","y":1974,"id":"1973/72-1057","sc":1,"ar":7,"sum":"The Court held that evidence obtained from improperly authorized wiretap applications, along with any evidence obtained from extensions of those applications, must be suppressed.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"United States v. Glover","cite":"736 F.3d 509","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/736/509/","ar":2,"by":{"0":"passim","1":"39","2":"1, 8, 10, 21"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"32","1":"27"}},{"t":"case","label":"United States v. Lawson","cite":"545 F.2d 557","y":1975,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/545/557/","by":{"0":"29"}},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"sum":"The Court ruled that there is an exception to the exclusionary rule for evidence gathered in \"good faith.\"","sumSrc":"Oyez","by":{"0":"26","1":"18, 28, 29, 36"}},{"t":"case","label":"United States v. Nelson","cite":"837 F.2d 1519","y":1988,"url":"https://www.courtlistener.com/c/F.2d/837/1519/","by":{"0":"30"}},{"t":"case","label":"United States v. North","cite":"735 F.3d 212","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/735/212/","by":{"0":"30, 36","2":"15"}},{"t":"case","label":"United States v. Radcliff","cite":"331 F.3d 1153","y":2003,"url":"https://www.courtlistener.com/c/F.3d/331/1153/","by":{"0":"12, 26","1":"10, 38","2":"11"}},{"t":"case","label":"United States v. Robertson","cite":"504 F.2d 289","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/504/289/","by":{"0":"29"}},{"t":"case","label":"United States v. Swann","cite":"526 F.2d 147","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/526/147/","by":{"0":"30"}},{"t":"case","label":"United States v. Timmreck","cite":"441 U.S. 780","y":1979,"id":"1978/78-744","sc":1,"sum":"A conviction based on a guilty plea is not subject to collateral attack when all that can be shown is a formal violation of Rule 11. Such a violation is neither constitutional nor jurisdictional. Nor can any claim reasonably be made that the error here resulted in a \"complete miscarriage of justice\" or in a proceeding \"inconsistent with the rudimentary demands of fair procedure.\" Hill v. United States, 368 U. S. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"United States v. Vigi","cite":"515 F.2d 290","y":1975,"url":"https://www.courtlistener.com/c/F.2d/515/290/","by":{"0":"29"}},{"t":"case","label":"Weinberg v. United States","cite":"126 F.2d 1004","y":1942,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/126/1004/","by":{"0":"37"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"3, 26","1":"27, 28, 34, 36, 39","2":"2, 9, 20, 21"}},{"t":"law","label":"Pub. L. No. 99-508","url":"https://www.govinfo.gov/link/statute/100/1848","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2510","url":"https://www.law.cornell.edu/uscode/text/18/2510","subs":["(9)","(11)","(4)","(12)"],"stext":{"head":"§2510. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) \"wire communication\" means any aural transfer made in whole or in part through the use of facilities for the transmission of communications by the aid of wire, cable, or other like connection between the point of origin and the point of reception (including the use of such connection in a switching station) furnished or operated by any person engaged in providing or operating such facilities for the transmission of interstate or foreign communications or communications affecting interstate or foreign commerce;"],[1,"(2) \"oral communication\" means any oral communication uttered by a person exhibiting an expectation that such communication is not subject to interception under circumstances justifying such expectation, but such term does not include any electronic communication;"],[1,"(3) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, and any territory or possession of the United States;"],[1,"(4) \"intercept\" means the aural or other acquisition of the contents of any wire, electronic, or oral communication through the use of any electronic, mechanical, or other device.1"],[1,"(5) \"electronic, mechanical, or other device\" means any device or apparatus which can be used to intercept a wire, oral, or electronic communication other than—"],[2,"(a) any telephone or telegraph instrument, equipment or facility, or any component thereof, (i) furnished to the subscriber or user by a provider of wire or electronic communication service in the ordinary course of its business and being used by the subscriber or user in the ordinary course of its business or furnished by such subscriber or user for connection to the facilities of such service and used in the ordinary course of its business; or (ii) being used by a provider of wire or electronic communication service in the ordinary course of its business, or by an investigative or law enforcement officer in the ordinary course of his duties;"],[2,"(b) a hearing aid or similar device being used to correct subnormal hearing to not better than normal;"],[1,"(6) \"person\" means any employee, or agent of the United States or any State or political subdivision thereof, and any individual, partnership, association, joint stock company, trust, or corporation;"],[1,"(7) \"Investigative or law enforcement officer\" means any officer of the United States or of a State or political subdivision thereof, who is empowered by law to conduct investigations of or to make arrests for offenses enumerated in this chapter, and any attorney authorized by law to prosecute or participate in the prosecution of such offenses;"],[1,"(8) \"contents\", when used with respect to any wire, oral, or electronic communication, includes any information concerning the substance, purport, or meaning of that communication;"],[1,"(9) \"Judge of competent jurisdiction\" means—"],[2,"(a) a judge of a United States district court or a United States court of appeals; and"],[2,"(b) a judge of any court of general criminal jurisdiction of a State who is authorized by a statute of that State to enter orders authorizing interceptions of wire, oral, or electronic communications;"],[1,"(10) \"communication common carrier\" has the meaning given that term in section 3 of the Communications Act of 1934;"],[1,"(11) \"aggrieved person\" means a person who was a party to any intercepted wire, oral, or electronic communication or a person against whom the interception was directed;"],[1,"(12) \"electronic communication\" means any transfer of signs, signals, writing, images, sounds, data, or intelligence of any nature transmitted in whole or in part by a wire, radio, electromagnetic, photoelectronic or photooptical system that affects interstate or foreign commerce, but does not include—"],[2,"(A) any wire or oral communication;"],[2,"(B) any communication made through a tone-only paging device;"],[2,"(C) any communication from a tracking device (as defined in section 3117 of this title); or"],[2,"(D) electronic funds transfer information stored by a financial institution in a communications system used for the electronic storage and transfer of funds;"],[1,"(13) \"user\" means any person or entity who—"],[2,"(A) uses an electronic communication service; and"],[2,"(B) is duly authorized by the provider of such service to engage in such use;"],[1,"(14) \"electronic communications system\" means any wire, radio, electromagnetic, photooptical or photoelectronic facilities for the transmission of wire or electronic communications, and any computer facilities or related electronic equipment for the electronic storage of such communications;"],[1,"(15) \"electronic communication service\" means any service which provides to users thereof the ability to send or receive wire or electronic communications;"],[1,"(16) \"readily accessible to the general public\" means, with respect to a radio communication, that such communication is not—"],[2,"(A) scrambled or encrypted;"],[2,"(B) transmitted using modulation techniques whose essential parameters have been withheld from the public with the intention of preserving the privacy of such communication;"],[2,"(C) carried on a subcarrier or other signal subsidiary to a radio transmission;"],[2,"(D) transmitted over a communication system provided by a common carrier, unless the communication is a tone only paging system communication; or"],[2,"(E) transmitted on frequencies allocated under part 25, subpart D, E, or F of part 74, or part 94 of the Rules of the Federal Communications Commission, unless, in the case of a communication transmitted on a frequency allocated under part 74 that is not exclusively allocated to broadcast auxiliary services, the communication is a two-way voice communication by radio;"],[1,"(17) \"electronic storage\" means—"],[2,"(A) any temporary, intermediate storage of a wire or electronic communication incidental to the electronic transmission thereof; and"],[2,"(B) any storage of such communication by an electronic communication service for purposes of backup protection of such communication;"],[1,"(18) \"aural transfer\" means a transfer containing the human voice at any point between and including the point of origin and the point of reception;"],[1,"(19) \"foreign intelligence information\", for purposes of section 2517(6) of this title, means—"],[2,"(A) information, whether or not concerning a United States person, that relates to the ability of the United States to protect against—"],[3,"(i) actual or potential attack or other grave hostile acts of a foreign power or an agent of a foreign power;"],[3,"(ii) sabotage or international terrorism by a foreign power or an agent of a foreign power; or"],[3,"(iii) clandestine intelligence activities by an intelligence service or network of a foreign power or by an agent of a foreign power; or"],[2,"(B) information, whether or not concerning a United States person, with respect to a foreign power or foreign territory that relates to—"],[3,"(i) the national defense or the security of the United States; or"],[3,"(ii) the conduct of the foreign affairs of the United States;"],[1,"(20) \"protected computer\" has the meaning set forth in section 1030; and"],[1,"(21) \"computer trespasser\"—"],[2,"(A) means a person who accesses a protected computer without authorization and thus has no reasonable expectation of privacy in any communication transmitted to, through, or from the protected computer; and"],[2,"(B) does not include a person known by the owner or operator of the protected computer to have an existing contractual relationship with the owner or operator of the protected computer for access to all or part of the protected computer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2510?type=usc&year=mostrecent&link-type=html"},"head":"§2510. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"passim, 6, 18","1":"2, 2","2":"passim"}},{"t":"usc","label":"18 U.S.C. § 2515","url":"https://www.law.cornell.edu/uscode/text/18/2515","stext":{"head":"§2515. Prohibition of use as evidence of intercepted wire or oral communications","paras":[[0,"Whenever any wire or oral communication has been intercepted, no part of the contents of such communication and no evidence derived therefrom may be received in evidence in any trial, hearing, or other proceeding in or before any court, grand jury, department, officer, agency, regulatory body, legislative committee, or other authority of the United States, a State, or a political subdivision thereof if the disclosure of that information would be in violation of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2515?type=usc&year=mostrecent&link-type=html"},"head":"§2515. Prohibition of use as evidence of intercepted wire or oral communications","tname":"Crimes and Criminal Procedure","by":{"0":"passim","1":"2","2":"8"}},{"t":"usc","label":"18 U.S.C. § 2516","url":"https://www.law.cornell.edu/uscode/text/18/2516","subs":["(1)"],"stext":{"head":"§2516. Authorization for interception of wire, oral, or electronic communications","paras":[[0,"(1) The Attorney General, Deputy Attorney General, Associate Attorney General,1 or any Assistant Attorney General, any acting Assistant Attorney General, or any Deputy Assistant Attorney General or acting Deputy Assistant Attorney General in the Criminal Division or National Security Division specially designated by the Attorney General, may authorize an application to a Federal judge of competent jurisdiction for, and such judge may grant in conformity with section 2518 of this chapter an order authorizing or approving the interception of wire or oral communications by the Federal Bureau of Investigation, or a Federal agency having responsibility for the investigation of the offense as to which the application is made, when such interception may provide or has provided evidence of—"],[1,"(a) any offense punishable by death or by imprisonment for more than one year under sections 2122 and 2274 through 2277 of title 42 of the United States Code (relating to the enforcement of the Atomic Energy Act of 1954), section 2284 of title 42 of the United States Code (relating to sabotage of nuclear facilities or fuel), or under the following chapters of this title: chapter 10 (relating to biological weapons), chapter 37 (relating to espionage), chapter 55 (relating to kidnapping), chapter 90 (relating to protection of trade secrets), chapter 105 (relating to sabotage), chapter 115 (relating to treason), chapter 102 (relating to riots), chapter 65 (relating to malicious mischief), chapter 111 (relating to destruction of vessels), or chapter 81 (relating to piracy);"],[1,"(b) a violation of section 186 or section 501(c) of title 29, United States Code (dealing with restrictions on payments and loans to labor organizations), or any offense which involves murder, kidnapping, robbery, or extortion, and which is punishable under this title;"],[1,"(c) any offense which is punishable under the following sections of this title: section 37 (relating to violence at international airports), section 43 (relating to animal enterprise terrorism), section 81 (arson within special maritime and territorial jurisdiction), section 201 (bribery of public officials and witnesses), section 215 (relating to bribery of bank officials), section 224 (bribery in sporting contests), subsection (d), (e), (f), (g), (h), or (i) of section 844 (unlawful use of explosives), section 1032 (relating to concealment of assets), section 1084 (transmission of wagering information), section 751 (relating to escape), section 832 (relating to nuclear and weapons of mass destruction threats), section 842 (relating to explosive materials), section 930 (relating to possession of weapons in Federal facilities), section 1014 (relating to loans and credit applications generally; renewals and discounts), section 1114 (relating to officers and employees of the United States), section 1116 (relating to protection of foreign officials), sections 1503, 1512, and 1513 (influencing or injuring an officer, juror, or witness generally), section 1510 (obstruction of criminal investigations), section 1511 (obstruction of State or local law enforcement), section 1581 (peonage), section 1582 (vessels for slave trade), section 1583 (enticement into slavery), section 1584 (involuntary servitude), section 1585 (seizure, detention, transportation or sale of slaves), section 1586 (service on vessels in slave trade), section 1587 (possession of slaves aboard vessel), section 1588 (transportation of slaves from United States), section 1589 (forced labor), section 1590 (trafficking with respect to peonage, slavery, involuntary servitude, or forced labor), section 1591 (sex trafficking of children by force, fraud, or coercion), section 1592 (unlawful conduct with respect to documents in furtherance of trafficking, peonage, slavery, involuntary servitude, or forced labor), section 1751 (Presidential and Presidential staff assassination, kidnapping, and assault), section 1951 (interference with commerce by threats or violence), section 1952 (interstate and foreign travel or transportation in aid of racketeering enterprises), section 1958 (relating to use of interstate commerce facilities in the commission of murder for hire), section 1959 (relating to violent crimes in aid of racketeering activity), section 1954 (offer, acceptance, or solicitation to influence operations of employee benefit plan), section 1955 (prohibition of business enterprises of gambling), section 1956 (laundering of monetary instruments), section 1957 (relating to engaging in monetary transactions in property derived from specified unlawful activity), section 659 (theft from interstate shipment), section 664 (embezzlement from pension and welfare funds), section 1343 (fraud by wire, radio, or television), section 1344 (relating to bank fraud), section 1992 (relating to terrorist attacks against mass transportation), sections 2251 and 2252 (sexual exploitation of children), section 2251A (selling or buying of children), section 2252A (relating to material constituting or containing child pornography), section 1466A (relating to child obscenity), section 2260 (production of sexually explicit depictions of a minor for importation into the United States), sections 2421, 2422, 2423, and 2425 (relating to transportation for illegal sexual activity and related crimes), sections 2312, 2313, 2314, and 2315 (interstate transportation of stolen property), section 2321 (relating to trafficking in certain motor vehicles or motor vehicle parts), section 2340A (relating to torture), section 1203 (relating to hostage taking), section 1029 (relating to fraud and related activity in connection with access devices), section 3146 (relating to penalty for failure to appear), section 3521(b)(3) (relating to witness relocation and assistance), section 32 (relating to destruction of aircraft or aircraft facilities), section 38 (relating to aircraft parts fraud), section 1963 (violations with respect to racketeer influenced and corrupt organizations), section 115 (relating to threatening or retaliating against a Federal official), section 1341 (relating to mail fraud), a felony violation of section 1030 (relating to computer fraud and abuse), section 351 (violations with respect to congressional, Cabinet, or Supreme Court assassinations, kidnapping, and assault), section 831 (relating to prohibited transactions involving nuclear materials), section 33 (relating to destruction of motor vehicles or motor vehicle facilities), section 175 (relating to biological weapons), section 175c (relating to variola virus), section 956 (conspiracy to harm persons or property overseas), a felony violation of section 1028 (relating to production of false identification documentation), section 1425 (relating to the procurement of citizenship or nationalization unlawfully), section 1426 (relating to the reproduction of naturalization or citizenship papers), section 1427 (relating to the sale of naturalization or citizenship papers), section 1541 (relating to passport issuance without authority), section 1542 (relating to false statements in passport applications), section 1543 (relating to forgery or false use of passports), section 1544 (relating to misuse of passports), section 1546 (relating to fraud and misuse of visas, permits, and other documents), or section 555 (relating to construction or use of international border tunnels);"],[1,"(d) any offense involving counterfeiting punishable under section 471, 472, or 473 of this title;"],[1,"(e) any offense involving fraud connected with a case under title 11 or the manufacture, importation, receiving, concealment, buying, selling, or otherwise dealing in narcotic drugs, marihuana, or other dangerous drugs, punishable under any law of the United States;"],[1,"(f) any offense including extortionate credit transactions under sections 892, 893, or 894 of this title;"],[1,"(g) a violation of section 5322 of title 31, United States Code (dealing with the reporting of currency transactions), or section 5324 of title 31, United States Code (relating to structuring transactions to evade reporting requirement prohibited);"],[1,"(h) any felony violation of sections 2511 and 2512 (relating to interception and disclosure of certain communications and to certain intercepting devices) of this title;"],[1,"(i) any felony violation of chapter 71 (relating to obscenity) of this title;"],[1,"(j) any violation of section 60123(b) (relating to destruction of a natural gas pipeline), section 46502 (relating to aircraft piracy), the second sentence of section 46504 (relating to assault on a flight crew with dangerous weapon), or section 46505(b)(3) or (c) (relating to explosive or incendiary devices, or endangerment of human life, by means of weapons on aircraft) of title 49;"],[1,"(k) any criminal violation of section 2778 of title 22 (relating to the Arms Export Control Act);"],[1,"(l) the location of any fugitive from justice from an offense described in this section;"],[1,"(m) a violation of section 274, 277, or 278 of the Immigration and Nationality Act (8 U.S.C. 1324, 1327, or 1328) (relating to the smuggling of aliens);"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2516?type=usc&year=mostrecent&link-type=html"},"head":"§2516. Authorization for interception of wire, oral, or electronic communications","tname":"Crimes and Criminal Procedure","by":{"0":"5, 20","1":"2"}},{"t":"usc","label":"18 U.S.C. § 2518","url":"https://www.law.cornell.edu/uscode/text/18/2518","subs":["(1)","(1)(c)","(3)","(3)(a)","(3)(b)","(4)","(5)","(6)","(8)(a)","(8)(d)","(10)(a)","(10)(a)(i)","(10)(a)(ii)","(10)(a)(iii)","(1)(a)","(1)(b)(iv)","(4)(b)","(4)(d)","(4)(e)","(8)"],"stext":{"head":"§2518. Procedure for interception of wire, oral, or electronic communications","paras":[[0,"(1) Each application for an order authorizing or approving the interception of a wire, oral, or electronic communication under this chapter shall be made in writing upon oath or affirmation to a judge of competent jurisdiction and shall state the applicant's authority to make such application. Each application shall include the following information:"],[1,"(a) the identity of the investigative or law enforcement officer making the application, and the officer authorizing the application;"],[1,"(b) a full and complete statement of the facts and circumstances relied upon by the applicant, to justify his belief that an order should be issued, including (i) details as to the particular offense that has been, is being, or is about to be committed, (ii) except as provided in subsection (11), a particular description of the nature and location of the facilities from which or the place where the communication is to be intercepted, (iii) a particular description of the type of communications sought to be intercepted, (iv) the identity of the person, if known, committing the offense and whose communications are to be intercepted;"],[1,"(c) a full and complete statement as to whether or not other investigative procedures have been tried and failed or why they reasonably appear to be unlikely to succeed if tried or to be too dangerous;"],[1,"(d) a statement of the period of time for which the interception is required to be maintained. If the nature of the investigation is such that the authorization for interception should not automatically terminate when the described type of communication has been first obtained, a particular description of facts establishing probable cause to believe that additional communications of the same type will occur thereafter;"],[1,"(e) a full and complete statement of the facts concerning all previous applications known to the individual authorizing and making the application, made to any judge for authorization to intercept, or for approval of interceptions of, wire, oral, or electronic communications involving any of the same persons, facilities or places specified in the application, and the action taken by the judge on each such application; and"],[1,"(f) where the application is for the extension of an order, a statement setting forth the results thus far obtained from the interception, or a reasonable explanation of the failure to obtain such results."],[0,"(2) The judge may require the applicant to furnish additional testimony or documentary evidence in support of the application."],[0,"(3) Upon such application the judge may enter an ex parte order, as requested or as modified, authorizing or approving interception of wire, oral, or electronic communications within the territorial jurisdiction of the court in which the judge is sitting (and outside that jurisdiction but within the United States in the case of a mobile interception device authorized by a Federal court within such jurisdiction), if the judge determines on the basis of the facts submitted by the applicant that—"],[1,"(a) there is probable cause for belief that an individual is committing, has committed, or is about to commit a particular offense enumerated in section 2516 of this chapter;"],[1,"(b) there is probable cause for belief that particular communications concerning that offense will be obtained through such interception;"],[1,"(c) normal investigative procedures have been tried and have failed or reasonably appear to be unlikely to succeed if tried or to be too dangerous;"],[1,"(d) except as provided in subsection (11), there is probable cause for belief that the facilities from which, or the place where, the wire, oral, or electronic communications are to be intercepted are being used, or are about to be used, in connection with the commission of such offense, or are leased to, listed in the name of, or commonly used by such person."],[0,"(4) Each order authorizing or approving the interception of any wire, oral, or electronic communication under this chapter shall specify—"],[1,"(a) the identity of the person, if known, whose communications are to be intercepted;"],[1,"(b) the nature and location of the communications facilities as to which, or the place where, authority to intercept is granted;"],[1,"(c) a particular description of the type of communication sought to be intercepted, and a statement of the particular offense to which it relates;"],[1,"(d) the identity of the agency authorized to intercept the communications, and of the person authorizing the application; and"],[1,"(e) the period of time during which such interception is authorized, including a statement as to whether or not the interception shall automatically terminate when the described communication has been first obtained."],[0,"An order authorizing the interception of a wire, oral, or electronic communication under this chapter shall, upon request of the applicant, direct that a provider of wire or electronic communication service, landlord, custodian or other person shall furnish the applicant forthwith all information, facilities, and technical assistance necessary to accomplish the interception unobtrusively and with a minimum of interference with the services that such service provider, landlord, custodian, or person is according the person whose communications are to be intercepted. Any provider of wire or electronic communication service, landlord, custodian or other person furnishing such facilities or technical assistance shall be compensated therefor by the applicant for reasonable expenses incurred in providing such facilities or assistance. Pursuant to section 2522 of this chapter, an order may also be issued to enforce the assistance capability and capacity requirements under the Communications Assistance for Law Enforcement Act."],[0,"(5) No order entered under this section may authorize or approve the interception of any wire, oral, or electronic communication for any period longer than is necessary to achieve the objective of the authorization, nor in any event longer than thirty days. Such thirty-day period begins on the earlier of the day on which the investigative or law enforcement officer first begins to conduct an interception under the order or ten days after the order is entered. Extensions of an order may be granted, but only upon application for an extension made in accordance with subsection (1) of this section and the court making the findings required by subsection (3) of this section. The period of extension shall be no longer than the authorizing judge deems necessary to achieve the purposes for which it was granted and in no event for longer than thirty days. Every order and extension thereof shall contain a provision that the authorization to intercept shall be executed as soon as practicable, shall be conducted in such a way as to minimize the interception of communications not otherwise subject to interception under this chapter, and must terminate upon attainment of the authorized objective, or in any event in thirty days. In the event the intercepted communication is in a code or foreign language, and an expert in that foreign language or code is not reasonably available during the interception period, minimization may be accomplished as soon as practicable after such interception. An interception under this chapter may be conducted in whole or in part by Government personnel, or by an individual operating under a contract with the Government, acting under the supervision of an investigative or law enforcement officer authorized to conduct the interception."],[0,"(6) Whenever an order authorizing interception is entered pursuant to this chapter, the order may require reports to be made to the judge who issued the order showing what progress has been made toward achievement of the authorized objective and the need for continued interception. Such reports shall be made at such intervals as the judge may require."],[0,"(7) Notwithstanding any other provision of this chapter, any investigative or law enforcement officer, specially designated by the Attorney General, the Deputy Attorney General, the Associate Attorney General, or by the principal prosecuting attorney of any State or subdivision thereof acting pursuant to a statute of that State, who reasonably determines that—"],[1,"(a) an emergency situation exists that involves—"],[2,"(i) immediate danger of death or serious physical injury to any person,"],[2,"(ii) conspiratorial activities threatening the national security interest, or"],[2,"(iii) conspiratorial activities characteristic of organized crime,"],[1,"that requires a wire, oral, or electronic communication to be intercepted before an order authorizing such interception can, with due diligence, be obtained, and"],[1,"(b) there are grounds upon which an order could be entered under this chapter to authorize such interception,"],[0,"may intercept such wire, oral, or electronic communication if an application for an order approving the interception is made in accordance with this section within forty-eight hours after the interception has occurred, or begins to occur. In the absence of an order, such interception shall immediately terminate when the communication sought is obtained or when the application for the order is denied, whichever is earlier. In the event such application for approval is denied, or in any other case where the interception is terminated without an order having been issued, the contents of any wire, oral, or electronic communication intercepted shall be treated as having been obtained in violation of this chapter, and an inventory shall be served as provided for in subsection (d) of this section on the person named in the application."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2518?type=usc&year=mostrecent&link-type=html"},"head":"§2518. Procedure for interception of wire, oral, or electronic communications","tname":"Crimes and Criminal Procedure","by":{"0":"5, 5, 35, 5, 38, passim, 6, 6, 7, 28, 5, 7, 35, 38, 7, 8, 8, 8, 18, 19, 19, passim, 19","1":"2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"3, 6, 13, 16, 5, 12, 6, 17, 18, 8, 18, 20, 21, passim"}},{"t":"usc","label":"18 U.S.C. § 3041","url":"https://www.law.cornell.edu/uscode/text/18/3041","subs":["(1964)"],"by":{"0":"6"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"rule","label":"Fed. R. Crim. P. 41","url":"https://www.law.cornell.edu/rules/frcrmp/rule_41","subs":["(b)"],"by":{"0":"35, 37"}},{"t":"case","label":"Aday v. Superior Court","cite":"362 P.2d 47","y":1961,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/362/47/","sum":"Describing Aday as the “leading case” and stating that its rule “is sound”.","sumSrc":"brief:1","by":{"1":"34"}},{"t":"case","label":"Arizona v. Evans","cite":"514 U.S. 1","y":1995,"id":"1994/93-1660","sc":1,"sum":"The Court held that the Supreme Court has jurisdiction to review cases from state courts that deal primarily with federal law. The Court also held that the Fourth Amendment was designed to protect against intrusions into a home or onto private property, or the conduct of police officers. The exclusionary rule therefore does not apply to the conduct of judicial officers.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Davis v. United States","cite":"564 U.S. 229","y":2011,"id":"2010/09-11328","sc":1,"sum":"The Court held that the good-faith exception to the exclusionary rule applies to a search that was authorized by precedent at the time of the search, but was subsequently ruled unconstitutional.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Groh v. Ramirez","cite":"540 U.S. 551","y":2004,"id":"2003/02-811","sc":1,"sum":"Yes and yes. Justice John Paul Stevens delivered the Court's 5-4 opinion holding that the search was \"unreasonable\" under the Fourth Amendment. Groh's warrant was invalid because it did not meet the Fourth Amendment requirement that a warrant particularly describe the persons or things to be seized.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Herring v. United States","cite":"555 U.S. 135","y":2009,"id":"2008/07-513","sc":1,"sum":"The Court found that a criminal defendant's Fourth Amendment rights were not violated when he was unlawfully searched due to isolated negligence of police and not \"systematic error or reckless disregard of constitutional requirements.\"","sumSrc":"Oyez","by":{"1":"29, 36"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"sum":"The Court ruled that the general rule excluding evidence obtained in violation of the Fourth Amendment does not apply to the \"knock-and-announce\" rule.","sumSrc":"Oyez","by":{"1":"35, 36"}},{"t":"case","label":"Illinois v. Krull","cite":"480 U.S. 340","y":1987,"id":"1986/85-608","sc":1,"sum":"The Supreme Court held that the exclusionary rule does not apply because the officer acted in good faith. The officer’s reliance on the unconstitutional law was objectively reasonable when he conducted the search. Excluding the evidence in this case would not support the policy behind the exclusionary rule to deter police misconduct.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"(III) Cases—Continued: Murray v. United States","cite":"487 U.S. 533","y":1988,"id":"1987/86-995","sc":1,"sum":"The Court held that evidence that would be excluded under the Fourth Amendment is admissible if it comes from an independent source.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Nix v. Williams","cite":"467 U.S. 431","y":1984,"id":"1983/82-1651","sc":1,"sum":"The Court relied on the \"inevitable discovery doctrine,\" as it held that the exclusionary rule did not apply to the child's body as evidence since it was clear that the volunteer search teams would have discovered the body even absent Williams's statements.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Pennsylvania Bd. of Prob. & Parole v. Scott","cite":"524 U.S. 357","y":1998,"id":"1997/97-581","sc":1,"sum":"In a 5-to-4 decision, the Court held that the federal exclusionary rule does not apply to parole revocation hearings. Noting that the exclusionary rule is not constitutionally mandated, the Court explained that it applies only in situations where its deterrent benefits outweigh the utilities that accompany the consideration of reliable, probative evidence.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"People v. Defore","cite":"150 N.E. 585","y":1926,"url":"https://www.courtlistener.com/c/N.E./150/585/","by":{"1":"40"}},{"t":"case","label":"Sanchez-Llamas v. Oregon","cite":"548 U.S. 331","y":2006,"id":"2005/04-10566","sc":1,"sum":"The Court affirmed the Oregon Supreme Court and ruled that evidence obtained in violation of Article 36 of the Vienna Convention need not be excluded from trial.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"United States v. Barajas","cite":"710 F.3d 1102","y":2013,"url":"https://www.courtlistener.com/c/F.3d/710/1102/","sum":"Noting circuit conflict on the good-faith issue.","sumSrc":"brief:1","by":{"1":"30"}},{"t":"case","label":"United States v. Calandra","cite":"414 U.S. 338","y":1974,"id":"1973/72-734","sc":1,"sum":"The Supreme Court held that the exclusionary rule does not apply in grand jury proceedings. The purpose of a grand jury is to determine whether a crime was committed and whether to charge someone in connection with that crime. Using the exclusionary rule would interfere with that purpose. The exclusionary rule is also meant to deter police misconduct, not provide a new constitutional right.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"United States v. Christine","cite":"687 F.2d 749","y":1982,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/687/749/","sum":"Describing Aday as the “leading case” and stating that its rule “is sound”.","sumSrc":"brief:1","by":{"1":"34"}},{"t":"case","label":"United States v. Cunningham","cite":"113 F.3d 289","y":1997,"url":"https://www.courtlistener.com/c/F.3d/113/289/","by":{"1":"38"}},{"t":"case","label":"United States v. Grubbs","cite":"547 U.S. 90","y":2006,"id":"2005/04-1414","sc":1,"sum":"Justice Antonin Scalia, in the majority opinion, wrote that under the Fourth Amendment's particularity requirement a warrant need not set out the conditions that trigger it, only the place to be searched and the persons or things to be searched for. The fact that the triggering conditions were included in the affidavit, even if they were never showed to Grubbs, was therefore sufficient.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"United States v. Holden","cite":"603 Fed. Appx. 744","y":2015,"url":"https://www.courtlistener.com/c/Fed.%20Appx./603/744/","by":{"1":"38"}},{"t":"case","label":"United States v. Houston","cite":"665 F.3d 991","y":2012,"url":"https://www.courtlistener.com/c/F.3d/665/991/","by":{"1":"29"}},{"t":"case","label":"United States v. Krueger","cite":"809 F.3d 1109","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/1109/","by":{"1":"29"}},{"t":"case","label":"United States v. Lomeli","cite":"676 F.3d 734","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/676/734/","sum":"Noting that the district court had treated subparagraphs (i) and (ii) as identical and held that suppression was required under both.","sumSrc":"brief:2","by":{"1":"24","2":"11, 17"}},{"t":"case","label":"United States v. Malekzadeh","cite":"855 F.2d 1492","y":1988,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/855/1492/","by":{"1":"30"}},{"t":"case","label":"United States v. Moore","cite":"41 F.3d 370","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/41/370/","by":{"1":"38","2":"5"}},{"t":"case","label":"United States v. Ojeda Rios","cite":"495 U.S. 257","y":1990,"id":"1989/89-61","sc":1,"sum":"During a criminal investigation, the Government secured a series of court orders authorizing electronic surveillance of respondents, as mandated by Title III of the Omnibus Crime Control and Safe Streets Act of 1968, 18 U. S. C. §2510 et seq. Section 2518(8)(a) requires, in pertinent part, that: (1) recording \"shall be done in such way as will protect the recording from editing or other alterations\"; (2) …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"17, 18"}},{"t":"case","label":"United States v. Pitts","cite":"173 F.3d 677","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/173/677/","by":{"1":"34"}},{"t":"case","label":"United States v. Ramirez","cite":"112 F.3d 849","y":1997,"url":"https://www.courtlistener.com/c/F.3d/112/849/","by":{"1":"7, 14, 25"}},{"t":"case","label":"United States v. Rodriguez","cite":"968 F.2d 130","y":1992,"url":"https://www.courtlistener.com/c/F.2d/968/130/","by":{"1":"6"}},{"t":"case","label":"United States v. Scurry","cite":"821 F.3d 1","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1/","by":{"1":"5, 39"}},{"t":"case","label":"United States v. Sells","cite":"463 F.3d 1148","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/463/1148/","by":{"1":"33, 39"}},{"t":"case","label":"United States v. Soto-Camargo","cite":"2015 WL 3823020","y":2015,"court":"D. Kan. June 19","by":{"1":"7"}},{"t":"case","label":"United States v. Vasquez-Garcia","cite":"2014 WL 7359490","y":2014,"court":"D. Kan. Dec. 23","by":{"1":"7"}},{"t":"case","label":"Utah v. Strieff","cite":"136 S. Ct. 2056","y":2016,"id":"2015/14-1373","sc":1,"sum":"The Court determined that, in the absence of flagrant police misconduct, the discovery of a valid, pre-existing, and untainted arrest warrant attenuated the connection between the unconstitutional investigatory stop and the evidence seized incident to the lawful arrest.","sumSrc":"Oyez","by":{"1":"33","2":"21"}},{"t":"case","label":"Waller v. Georgia","cite":"467 U.S. 39","y":1984,"id":"1983/83-321","sc":1,"sum":"The Court held that the Sixth Amendment right to a public trial applied to suppression hearings.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Wong Sun v. United States","cite":"371 U.S. 471","y":1963,"id":"1962/36","sc":1,"sum":"The Supreme Court held that the police did not have probable cause to justify the arrests. With regard to Toy, the court should exclude all evidence found during the search because they are the “fruits” of an unlawful search. The unsigned statement was not corroborated, so it gave no basis for conviction. Sun’s unsigned confession and evidence against him were admissible.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 90-351","url":"https://www.govinfo.gov/link/statute/82/211","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(D)"],"by":{"1":"2, 3, 2, 2, 3"}},{"t":"usc","label":"21 U.S.C. § 843","url":"https://www.law.cornell.edu/uscode/text/21/843","subs":["(b)"],"by":{"1":"2"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"1":"2, 3"}},{"t":"usc","label":"21 U.S.C. § 856","url":"https://www.law.cornell.edu/uscode/text/21/856","subs":["(a)(1)","(a)(2)"],"by":{"1":"2, 2, 2"}},{"t":"usc","label":"21 U.S.C. § 860","url":"https://www.law.cornell.edu/uscode/text/21/860","by":{"1":"3"}},{"t":"usc","label":"47 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/47/1002","subs":["(a)(1)"],"by":{"1":"6"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(a)"],"by":{"1":"40"}},{"t":"case","label":"Chaidez v. United States","cite":"568 U.S. 342","y":2013,"id":"2012/11-820","sc":1,"sum":"The Court found that the Padilla rule created an entirely new rule regarding ineffective assistance of counsel and therefore did not apply to persons whose conviction became final before its announcement.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Katz v. United States","cite":"389 U.S. 347","y":1967,"id":"1967/35","sc":1,"sum":"The Court found that the government putting a tap on a public payphone is a violation of the users' Fourth Amendment rights.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Olmstead v. United States","cite":"277 U.S. 438","y":1928,"id":"1900-1940/277us438","sc":1,"sum":"The Court held that incriminating evidence obtained through wiretapping did not violate the Fourth and Fifth Amendment rights of those whose conversations were tapped.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"sum":"The Court held that a conviction for resisting arrest counts as a violent felony under the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"United States v. Callum","cite":"410 F.3d 571","y":2005,"url":"https://www.courtlistener.com/c/F.3d/410/571/","by":{"2":"11"}},{"t":"case","label":"United States v. Fudge","cite":"325 F.3d 910","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/325/910/","by":{"2":"11"}},{"t":"case","label":"United States v. Gray","cite":"521 F.3d 514","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/521/514/","by":{"2":"11"}},{"t":"case","label":"United States v. Traitz","cite":"871 F.2d 368","y":1989,"url":"https://www.courtlistener.com/c/F.2d/871/368/","by":{"2":"5"}},{"t":"case","label":"United States v. Vest","cite":"813 F.2d 477","y":1987,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/813/477/","by":{"2":"21"}}]};